import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"47、【困】 坎下兑上","description":"周易口诀义 - 47、【困】 坎下兑上","frontmatter":{"title":"47、【困】 坎下兑上","description":"周易口诀义 - 47、【困】 坎下兑上"},"headers":[],"relativePath":"zh/classics/koujueyi/049.md","filePath":"zh/classics/koujueyi/049.md"}'),r={name:"zh/classics/koujueyi/049.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_47、【困】-坎下兑上" tabindex="-1">47、【困】 坎下兑上 <a class="header-anchor" href="#_47、【困】-坎下兑上" aria-label="Permalink to “47、【困】 坎下兑上”">​</a></h1><p>彖曰：「困」，刚揜也。险以说，困而不失其所，亨，其唯君子乎！「贞大人吉」，以刚中也；「有言不信」，尚口乃穷也。</p><p>象曰：泽无水，困，君子以致命遂志。</p><p>初六：臀困于株木，入于幽谷，三岁不觌。</p><p>象曰：「入于幽谷」，幽不明也。</p><p>九二：困于酒食，朱绂方来，利用亨祀。征凶无咎。</p><p>象曰：「困于酒食」，中有庆也。</p><p>六三：困于石，据于蒺藜，入于其宫，不见其妻，凶。</p><p>象曰：「据于蒺藜」，乘刚也。「入于其宫，不见其妻」，不祥也。</p><p>九四：来徐徐，困于金车，吝，有终。</p><p>象曰：「来徐徐」，志在下也。虽不当位，有与也。</p><p>九五：劓刖，困于赤绂，乃徐有说，利用祭祀。</p><p>象曰：「劓刖」，志未得也。「乃徐有说」，以中直也。「利用祭祀」，受福也。</p><p>上六：困于葛藟，于臲卼，曰动悔有悔，征吉。</p><p>象曰：「困于葛藟」，未当也；「动悔有悔」，吉行也。</p><p>解读</p><p>「困，亨」者，「困」者，穷阨委顿之名，道乖力疲之义。小人遭困，则穷斯滥矣。君子处之，贞节不改，而不失其通之道，困而获济，故曰「困，亨」。困而不能得通，小人也。「贞大人吉，无咎」者，处困不滥而能自通，此唯体正修德之人，处困而能保之，然后「吉无咎」也。「有言不信」者，当困之时，欲希济困，必须修身慎行，立德立诚，而乃巧辞饰言以求其济，人何以信？转益困穷也。象曰「泽无水，困」者，水在泽下，泽中万物枯稿，困之象也。「君子以致命遂志」者，君子守道而处，虽遭困厄之世，而不渝滥以謟世俗。假使致命丧身，固当守节不移，以遂高尚之志，故素书云「如其不遇，没身而已」是也。</p><p>「初六，臀困于株木，入于幽谷，三岁不觌」者，以阴爻最居穷下，即是沉滞穷困，居不得安，若处于株木之上，故曰「臀困于株木」也。处困之时，欲进即二隔其路，欲且处，又居之不安，惧于困危，遂乃逃窜，故曰「入于幽谷」也。困极即通，事之常理，不过数年，困危必释，可以出矣，故曰「三岁不觌」也。</p><p>「九二，困于酒食，朱绂方来，利用亨祀，征凶，无咎」者，以刚处中，以阳居正，又无偏应，体刚即能济困，居阴即以谦待物，物之所归也。处中即德行不邪，无应即心无私党，有此众美，即物皆归己，不胜饱饫，故曰「困于酒食」也。朱绂，南方祭服也。九二体属坎卦，坎为北方，言九二有此美德，阳明方物而来，即东西二方必至，故曰「朱绂方来」。四方归向，庶物丰盈，可以亨荐神明，克降其福，故曰「利用亨祀」也。盈而又进，倾败道也。以此征行，凶危交至，故「征凶」。凶祸自己所招，岂合咎怨他人，即得「无咎」也。</p><p>「六三，困于石，据于蒺藜，入于其宫，不见其妻，凶」者，石者，为物坚刚而不可入，谓九四也；蒺藜之草，有刺而不可践，谓九二也。六三以阴居阳，不正而处，上无应援，无所之适，志怀刚武，欲亲于四，四又不受，如石之坚；欲附九二，二又不许，犹如蒺藜，刺而难践，故曰「困于石，据于蒺藜」也。无应而行，失其配偶，譬之入于宫中而不见其妻，处困如斯，固其凶矣。「九四，来徐徐，困于金车，吝，有终」者，「徐徐」是疑惧不速之貌也；「金车」谓九二以刚处中，如车材强壮也。四欲就初六，惧九二为难，心怀疑惧，不敢速进，是困于九二之金车，故曰「来徐徐，困于金车」也。有应在初，而未相遇，是以有「吝」，以谦得物，故乃「有终」也。</p><p>「九五，劓刖，困于赤绂，乃徐有说，利用祭祀」者，以阳居阳而无谦逊，物则不附，怒其不来附己，乃行劓刖之刑，故异方之人，转更离叛，故曰「困于赤绂」矣。以刚居中，不昧所见，改修其道，以谦得众，故用宽徐，人悉归己，乃有喜悦，故曰「乃徐有说」。刚而处尊，而用中直，即可亨祭而获福庆，故曰「利用祭祀」也。</p><p>「上六：困于葛藟，于臲卼，曰动悔有悔，征吉」者，葛，蔓也；藟，缠绕貌。臲卼，摇动不安貌。上六处困之极，即是困极也。无应乘刚，行即被物缠绕，居则臲卼不安，故曰「困于葛藟，于臲卼」也。曰，思谋之辞也。凡物穷思变，极即谋通，处至困之地，何有通路？故须思谋。曰：我若守此，必见不济，谋逃逸可以免之。发意逃时，其悔乃生，故系辞云：「吉凶悔吝生乎动。」是初动而有忧悔，当奔逸冒险之时，又生忧悔，既出险外，即不虑危困，所以征行而获吉，故曰「动悔有悔，征吉」也。</p>',22)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
